package com.company.platform.inventory.infrastructure;
import com.company.platform.inventory.application.InventoryStore;import com.company.platform.inventory.domain.Inventory;import java.sql.Timestamp;import java.util.*;import org.springframework.jdbc.core.JdbcTemplate;import org.springframework.stereotype.Repository;
@Repository public class JdbcInventoryStore implements InventoryStore{private final JdbcTemplate jdbc;public JdbcInventoryStore(JdbcTemplate j){jdbc=j;}public Inventory save(Inventory i){jdbc.update("INSERT INTO inventory(id,tenant_id,product_id,warehouse_location_id,on_hand,reserved,committed,updated_at) VALUES(?,?,?,?,?,?,?,?) ON CONFLICT(id) DO UPDATE SET on_hand=?,reserved=?,committed=?,updated_at=?",i.id(),i.tenantId(),i.productId(),i.warehouseLocationId(),i.onHand(),i.reserved(),i.committed(),Timestamp.from(i.updatedAt()),i.onHand(),i.reserved(),i.committed(),Timestamp.from(i.updatedAt()));return i;}private Inventory map(java.sql.ResultSet r,int n)throws java.sql.SQLException{return Inventory.rehydrate((UUID)r.getObject("id"),(UUID)r.getObject("tenant_id"),(UUID)r.getObject("product_id"),(UUID)r.getObject("warehouse_location_id"),r.getBigDecimal("on_hand"),r.getBigDecimal("reserved"),r.getBigDecimal("committed"),r.getTimestamp("updated_at").toInstant());}public Optional<Inventory> findInventory(UUID t,UUID id){return jdbc.query("SELECT * FROM inventory WHERE tenant_id=? AND id=?",this::map,t,id).stream().findFirst();}public List<Inventory> findByProduct(UUID t,UUID p){if(p==null)return jdbc.query("SELECT * FROM inventory WHERE tenant_id=? ORDER BY updated_at DESC",this::map,t);return jdbc.query("SELECT * FROM inventory WHERE tenant_id=? AND product_id=? ORDER BY updated_at DESC",this::map,t,p);}}
